import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    roads = [(int(input[2 * i + 1]), int(input[2 * i + 2])) for i in range(n - 1)]

    adj = defaultdict(list)
    for i, (u, v) in enumerate(roads):
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    def dfs(u, p):
        nonlocal day
        repairs = []
        for v, idx in adj[u]:
            if v != p:
                repairs.extend(dfs(v, u))
        if len(repairs) % 2 == 1:
            repairs.append((u, 0))
        for i in range(0, len(repairs), 2):
            a, b = repairs[i], repairs[i + 1]
            day.append([a[1], b[1]])
        return repairs

    day = []
    dfs(1, -1)

    print(len(day))
    for d in day:
        print(len(d), *d)

if __name__ == "__main__":
    main()
